        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / PageSize);

    private int firstItemIndex => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int lastItemIndex => result is null || result.Items.Count == 0
        ? 0
        : firstItemIndex + result.Items.Count - 1;

    protected override async Task OnInitializedAsync()
    {
