+                <input type="checkbox" @bind="inStockOnly" />
+                In Stock Only
+            </label>
+        </div>
+
+        <div class="filter-actions">
+            <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
+            <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
+        </div>
+    </aside>
+
+    <!-- Main Content -->
+    <section class="catalog-main">
+        @if (hasError)
+        {
+            <div class="catalog-error">
+                <p>⚠️ Something went wrong while loading products.</p>
+                <button class="btn btn-primary" @onclick="RetryLoad">Try Again</button>
+            </div>
+        }
+        else if (isLoading)
+        {
+            <div class="catalog-loading">
+                <p>Loading products…</p>
+            </div>
+        }
+        else if (result is not null && result.Items.Count == 0)
+        {
+            <div class="catalog-empty">
+                <p>No products found matching your criteria.</p>
+                <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
+            </div>
+        }
+        else if (result is not null)
+        {
+            <!-- Toolbar -->
+            <div class="catalog-toolbar">
+                <div class="sort-control">
+                    <label for="sort-select">Sort by:</label>
+                    <select id="sort-select" @bind="sortBy" @bind:after="LoadProducts">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A–Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="results-summary">
+                    Showing @(firstItemIndex)–@(lastItemIndex) of @(result.TotalCount) products
+                </span>
+            </div>
+
+            <!-- Product Grid -->
+            <div class="product-grid">
+                @foreach (var product in result.Items)
+                {
+                    <ProductCard Product="product"
+                                 OnProductClick="HandleProductClick"
+                                 OnAddToCart="HandleAddToCart" />
+                }
+            </div>
+
+            <!-- Pagination -->
+            @if (totalPages > 1)
+            {
+                <nav class="catalog-pagination" aria-label="Product pages">
+                    <button class="btn btn-page"
+                            disabled="@(currentPage <= 1)"
+                            @onclick="() => GoToPage(currentPage - 1)">
+                        Previous
+                    </button>
+
+                    @foreach (var p in GetPageNumbers())
+                    {
+                        <button class="btn btn-page @(p == currentPage ? "active" : "")"
+                                @onclick="() => GoToPage(p)">
+                            @p
+                        </button>
+                    }
+
+                    <button class="btn btn-page"
+                            disabled="@(currentPage >= totalPages)"
+                            @onclick="() => GoToPage(currentPage + 1)">
+                        Next
+                    </button>
+                </nav>
+            }
+        }
+    </section>
+</div>
+
+@code {
+    private List<string>? categories;
+    private HashSet<string> selectedCategories = new();
+    private decimal? minPrice;
+    private decimal? maxPrice;
+    private bool inStockOnly;
+    private string sortBy = "price_asc";
+    private int currentPage = 1;
+    private const int PageSize = 12;
+
+    private PagedResult<Product>? result;
+    private bool isLoading = true;
+    private bool hasError;
+
+    private int totalPages => result is null || result.TotalCount == 0
+        ? 1
+        : (int)Math.Ceiling((double)result.TotalCount / PageSize);
+
+    private int firstItemIndex => result is null || result.Items.Count == 0
+        ? 0
+        : (result.Page - 1) * result.PageSize + 1;
+
+    private int lastItemIndex => result is null || result.Items.Count == 0
+        ? 0
+        : firstItemIndex + result.Items.Count - 1;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadInitialData();
+    }
+
+    private async Task LoadInitialData()
+    {
+        try
+        {
+            hasError = false;
+            isLoading = true;
+
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = SearchProducts();
+
+            categories = await categoriesTask;
+            result = await productsTask;
+        }
+        catch
+        {
+            hasError = true;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        try
+        {
+            hasError = false;
+            isLoading = true;
+            StateHasChanged();
+
+            result = await SearchProducts();
+        }
+        catch
+        {
+            hasError = true;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private Task<PagedResult<Product>> SearchProducts()
+    {
+        var filter = new ProductFilter(
+            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
+            MinPrice: minPrice,
+            MaxPrice: maxPrice,
+            InStockOnly: inStockOnly
+        );
+
+        return ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            selectedCategories.Add(category);
+        else
+            selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        sortBy = "price_asc";
+        currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > totalPages) return;
+        currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task RetryLoad()
+    {
+        await LoadInitialData();
+    }
+
+    [Parameter]
+    public EventCallback<Product> OnProductSelected { get; set; }
+
+    private async Task HandleProductClick(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private void HandleAddToCart(Product product)
+    {
+        // Add-to-cart logic handled by parent or future service
+    }
+
+    private IEnumerable<int> GetPageNumbers()
+    {
+        const int maxVisible = 5;
+        int start = Math.Max(1, currentPage - maxVisible / 2);
+        int end = Math.Min(totalPages, start + maxVisible - 1);
+        start = Math.Max(1, end - maxVisible + 1);
+
+        return Enumerable.Range(start, end - start + 1);
+    }
+}
+

toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 2rem;
    align-items: flex-start;
}

/* Sidebar */
.catalog-sidebar {
    flex: 0 0 25%;
    background: #f8f9fa;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.25rem;
}

.catalog-sidebar h3 {
    margin-top: 0;
    margin-bottom: 1rem;
    font-size: 1.2rem;
    border-bottom: 2px solid #dee2e6;
    padding-bottom: 0.5rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h4 {
    margin: 0 0 0.5rem;
    font-size: 0.95rem;
    color: #495057;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.price-inputs {
    display: flex;
    gap: 0.75rem;
}

.price-inputs label {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    font-size: 0.85rem;
    color: #6c757d;
    flex: 1;
}

.price-inputs input {
    padding: 0.4rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    width: 100%;
    box-sizing: border-box;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

/* Main content area */
.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1.25rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 6px;
    border: 1px solid #dee2e6;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 0.9rem;
}

.results-summary {
    font-size: 0.9rem;
    color: #6c757d;
}

/* Product grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

/* Pagination */
.catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.35rem;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

.btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #dee2e6;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-page:hover:not(:disabled) {
    background: #e9ecef;
}

.btn-page.active {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

.btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Buttons */
.btn {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover {
    background: #5c636a;
}

/* States */
.catalog-loading,
.catalog-empty,
.catalog-error {
    text-align: center;
    padding: 3rem 1rem;
    color: #6c757d;
}

.catalog-error {
    color: #dc3545;
}

.loading-text {
    font-size: 0.85rem;
    color: #adb5bd;
}

